import json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
read=lambda p:json.loads((root/p).read_text())
version=read('dist/build.json')['version']
lines=['# F1M — F1 25 driving calibration', '',f'รุ่น `{version}` · ฐาน `7cfce508201fcfd0` · 27 ตุลาคม 2026', '', '## เกณฑ์อ้างอิงและขอบเขต', '', 'ใช้ median minimum/apex speed รายโค้งจากหลายผู้เล่นของ F1 25 ตามไฟล์ที่ผู้ใช้ส่ง และตรวจตารางต้นทางของ Driver Dojo เพิ่มเติม ไม่ใช่ telemetry F1 จริงหรือรอบของ Max Verstappen ไม่อ้างว่าใช้ source code หรือ physics ของ EA', '', 'EA อธิบายการพัฒนา handling จาก feedback ของผู้เล่นและ sim racers และอธิบายผลของ downforce, transmission, brake balance และยางต่อการขับ ข้อมูลเหล่านี้ใช้เป็นหลักการ ส่วนสูตรและตัวควบคุมด้านล่างเป็นงานของ F1M', '', '## สิ่งที่เปลี่ยน', '', '1. สร้างถนน Bahrain/Suzuka ใหม่จากพิกัดแผนที่ telemetry ที่ปรับแนวและขนาดเข้ากับโลกเดิม เก็บ main/pit corridor และระดับความสูงเดิม โดยมีถนนเดียวกันสำหรับภาพกับฟิสิกส์ เป็น reconstruction โดยประมาณ ไม่ใช่ LiDAR', '2. แก้ Shanghai T14 จากโค้ง schematic ที่บางจุดมีรัศมีประมาณ 6–7 เมตร ต่ำกว่าครึ่งความกว้างถนน 7.7 เมตร เป็น hairpin ต่อเนื่องรัศมีต่ำสุดประมาณ 19.6 เมตรในช่วงที่ตรวจ พร้อมสร้างไลน์ขับใหม่', '3. ใช้ spatial racing path และ minimum-curvature line ทั้งสามสนาม ให้เข้า–apex–ออกโค้งต่อเนื่องบนพิกัดถนนจริง พร้อมไลน์แซง/ตาม/หลบและข้อจำกัดพื้นที่ของคู่แข่ง', '4. ล็อกแผนไลน์เข้าโค้งระหว่างเบรกหนักจนผ่าน apex เพื่อไม่เปลี่ยนใจข้ามฝั่งถนนกลาง hairpin; recovery และ pit ยังมีสิทธิ์เหนือแผนนี้', '5. เพิ่มตัวคุมมุมลื่นยางหน้า: คลายพวงมาลัยเมื่อคำสั่งเลี้ยวเกินช่วงแรงเกาะที่ใช้ได้ แทนการถือพวงมาลัยเต็มแล้วไถลออก โดยไม่แก้พิกัด ความเร็ว หรือ core physics', '6. แก้ braking envelope ให้ประเมิน downforce ที่ความเร็วปลายการคำนวณจริงในแต่ละช่วง ด้วย fixed-point iteration เดิมใช้ความเร็ว cap บนทางตรงประเมินกำลังเบรก แล้วค่อยลดความเร็ว ทำให้ประเมินแรงกดอากาศสูงเกินจริงก่อนโค้งช้า', '7. เผื่อ downforce สำหรับ wake ที่อาจเปลี่ยนในอายุแผน 100 ms และสงวนแรงเกาะเมื่ออยู่ใกล้คู่แข่ง', '8. แก้แผน recovery จากขอบถนนให้เริ่มจากตำแหน่งที่วัดจริงและหันกลับเข้าด้านใน ไม่สืบทอดความเร็วด้านข้างของแผนแซงเก่า; ไม่ย้ายรถหรือปิด collision guard', '9. ปรับ thermal capacity/heat exchange ผ่าน vehicle preset เดิม และปรับ wear ของ compounds ให้การเสื่อมไม่ทำให้แรงเกาะตกหนักภายในสองรอบ คงสมการพลังงาน/ความร้อน/การสึกและผลฝนเดิม', '10. ปรับความต่อเนื่องของคันเร่งและใช้แรงต้านอากาศชะลอความเร็วส่วนเกินเล็กน้อยเมื่อแผนยังถึงได้ การเบรกจริง/ฉุกเฉิน/รถขวางยังตอบสนองทันที', '', 'ยังคง frozen solver/controller/C0 และโมเดลรถเดิม ไม่มีการลดกราฟิก DPR เงา หรือระยะมอง ไม่มีการบังคับรถให้มีความเร็วตรงตัวเลขอ้างอิง', '', '## เปรียบเทียบครบ 49 โค้ง', '', 'รถเดี่ยวหมายเลข 1, seed 19, Medium, วิ่ง 2 รอบ ใช้รอบสอง ความเร็วเกมในตารางคือ minimum ภายใน ±35 เมตรรอบ marker ของเกม วัดทุก 0.05 วินาที จึงเป็นการเทียบลักษณะความเร็ว ไม่ได้ยืนยันว่า marker/apex ของสองเกมตรงกันทุกจุด ตัวเลขก่อนมาจากฐาน 7cfce508201fcfd0', '', '| สนาม | จำนวนโค้ง | ต่างไม่เกิน ±20% ก่อน → หลัง |', '|---|---:|---:|']
totalB=totalA=0
for t in ['bahrain','shanghai','suzuka']:
 b=read('reports/F125_49_BEFORE_'+t+'.json');a=read('reports/F125_49_AFTER_'+t+'.json')
 bc=sum(abs(c['laps']['2']['nearMin']/c['ref']-1)<=.2 for c in b['corners']);ac=sum(abs(c['laps']['2']['nearMin']/c['ref']-1)<=.2 for c in a['corners']);totalB+=bc;totalA+=ac
 lines.append(f'| {t} | {len(a["corners"])} | {bc} → {ac} |')
lines+= [f'| รวม | 49 | **{totalB} → {totalA}** |','']
for t in ['bahrain','shanghai','suzuka']:
 b=read('reports/F125_49_BEFORE_'+t+'.json');a=read('reports/F125_49_AFTER_'+t+'.json')
 lines+=['### '+t,'','| โค้ง | F1 25 | เกมเดิม | รุ่นนี้ | ต่างจาก F1 25 |','|---|---:|---:|---:|---:|']
 for c,d in zip(b['corners'],a['corners']):
  old=c['laps']['2']['nearMin'];new=d['laps']['2']['nearMin'];ref=d['ref'];lines.append(f'| T{d["number"]} | {ref:g} | {old:.1f} | {new:.1f} | {(new/ref-1)*100:+.1f}% |')
 lines+=['']
lines+=['## ตรวจแข่งหลายคัน', '', 'รถ 6 คัน seed 19 สนามละ 2 รอบ ตรวจ footprint รถสี่มุมทุก 0.1 วินาที เป็น sampled check ไม่ใช่ continuous proof', '', '| สนาม | ทุกคันจบใน (วินาที) | footprint สูงสุด / ครึ่งถนน (เมตร) | rejection / guard stop / retirement |', '|---|---:|---:|---|']
for t in ['bahrain','shanghai','suzuka']:
 a=read('reports/F125_GRID_'+t+'.json');assert a['finished'] and not a['stop'] and not a['rejections'] and not a['retired'];assert a['boundary']<=a['roadHalfWidth']+.05
 lines.append(f'| {t} | {a["time"]:.2f} | {a["boundary"]:.3f} / {a["roadHalfWidth"]:.1f} | 0 / 0 / 0 |')
lines+=['', 'npm test (28 jobs รวม regression ของ entry braking / steering slip / edge connector), build และ PWA static/service-worker tests ผ่าน รวม core checksum และ serial/worker parity เดิม ตรวจ geometry สะพาน Suzuka, pit cycles ทั้งสามสนาม, 1,980 transition plans และการเบรกคันหน้าขณะออกตัวเพิ่มเติม', '', 'Warm planning benchmark หลังแก้ braking envelope: ประมาณ 0.528 ms/plan ต่อ 1,000 แผนใน Node เทียบรุ่นก่อนประมาณ 0.401 ms/plan เป็นการเพิ่มงานคำนวณเพื่อความถูกต้อง ไม่อ้างว่าเพิ่ม Android FPS', '', '## สิ่งที่ยังไม่ตรงทั้งหมด', '', '- Shanghai T4/T13 ยังมีช่วงนิยาม apex กับจุดเร่งออกต่างกันอย่างเห็นได้ชัด และ T16 ยังช้ากว่าฐาน จึงไม่ลดความเร็วหรือย้าย marker เพื่อทำให้สถิติดูตรง', '- ชุดข้อมูลเป็น median ผู้เล่นหลายคน มีความต่างของ setup, fuel, tyre state และฝีมือ ค่า 46/49 ภายใน ±20% ไม่ใช่การรับรองว่า handling เหมือน F1 25 ทุกสถานการณ์', '- ยังไม่ได้วัด GPU/FPS หรือให้คนขับบน Android เครื่องจริงของผู้ใช้ รุ่นนี้ยืนยันจากฟิสิกส์ใน Node, โครงฉาก, build และ asset checks; ไม่รายงาน browser full-race หรือ Android QA ว่าผ่าน', '', '## แหล่งข้อมูล', '', '- https://www.ea.com/news/f1-25-qa', '- https://help.ea.com/en/articles/f1/f1-25/car-setups-guide/', '- https://driverdojo.app/tracks/bahrain.html', '- https://driverdojo.app/tracks/shanghai.html', '- https://driverdojo.app/tracks/suzuka.html', '', 'สำเนาข้อมูล 49 โค้ง: `docs/F125_ALL_CORNERS_SOURCE.md` · provenance และวิธีสร้างถนน: `engine/tracks/reference25/README.md`', '', '## ตรวจซ้ำ', '', '```sh', 'npm ci', 'npm test', 'npm run build', 'npm run test:pwa', 'F1M_TRACK23=shanghai node tests/f125-corner-comparison.mjs', 'F1M_TRACK23=bahrain AUDIT_LAPS=2 node tests/corner-speed-audit.mjs', 'F1M_TRACK23=shanghai AUDIT_LAPS=2 node tests/corner-speed-audit.mjs', 'F1M_TRACK23=suzuka AUDIT_LAPS=2 node tests/corner-speed-audit.mjs', '```', '']
five=read('reports/F125_FIVE_LAPS_suzuka.json')
assert five['finished'] and not five['stop'] and not five['rejections'] and not five['retired']
assert five['boundary']<=five['roadHalfWidth']+.05
lines+=['## เรซยาว 5 รอบ','',f"Suzuka รถ 6 คัน 5 รอบ: จบครบ {five['time']:.2f} วินาที, rejection/guard stop/retirement = 0/0/0, sampled footprint สูงสุด {five['boundary']:.3f} เมตร เทียบครึ่งถนน {five['roadHalfWidth']:.1f} เมตร",'', 'หลักฐานกรณี Shanghai ก่อนแก้: `F125_SHANGHAI_EDGE_TRIAL.json` เป็นผลของตัวทดลองที่ไม่ใช้ ผลรุ่นส่งมอบอยู่ `F125_GRID_shanghai.json`','']
(root/'reports/F125_DRIVING_TH.md').write_text('\n'.join(lines))
print(version,totalB,totalA)
